import type { ControlUiSkin } from "@/components/control-ui/skin";

/*
 * "Rig" is THEME skin: brand lives in theme.css tokens (coral/near-black, --radius:0, grotesque)
 * + presentational skin.css. Config only names id, which scopes theme.css/skin.css — no per-slot
 * classes needed.
 */
export const skin: ControlUiSkin = { id: "rig" };

/* Only what a cva recipe cannot express: chamfer clip-path, corner ticks, scanline. Layered so app utilities still win. */

/* Pack-owned vars, off the theme contract; unlayered so the @layer components block below inherits them. */
[data-skin="rig"] {
  --rig-chamfer: 9px;
}

@layer base {
  :root[data-skin="rig"] body {
    background: repeating-linear-gradient(0deg, oklch(from var(--foreground) l c h / 0.05) 0 1px, transparent 1px 4px), var(--background);
  }
}

@layer components {
  /* Squared + diagonal cut on two corners; clip-path removes border there, so outlined controls use
   * an inset ring instead. Hard offset shadow rides filter:drop-shadow (honors clip-path shape;
   * box-shadow would get clipped away). Resting=flat, hover=shadow, press=sink. */
  [data-skin="rig"] [data-control-family][data-control="true"] {
    clip-path: polygon(
      0 0,
      calc(100% - var(--rig-chamfer)) 0,
      100% var(--rig-chamfer),
      100% 100%,
      var(--rig-chamfer) 100%,
      0 calc(100% - var(--rig-chamfer))
    );
    text-shadow: none;
    letter-spacing: 0.01em;
    transition-property: transform, filter;
    transition-timing-function: var(--ease-standard);
  }

  [data-skin="rig"] [data-control-family="button"][data-control="true"] {
    --cui-button-radius: 0px;
    --cui-button-shadow: none;
    --cui-button-hover-shadow: none;
    --cui-button-press-shadow: none;
    border: 0;
    font-weight: 600;
  }

  [data-skin="rig"] [data-control-family="field"][data-control="true"] {
    --cui-field-radius: 0px;
    --cui-field-border-width: 0px;
    --cui-field-shadow: none;
  }

  [data-skin="rig"] [data-control-family="pagination"][data-control="true"] {
    --cui-pagination-link-radius: 0px;
    --cui-pagination-link-shadow: none;
  }

  [data-skin="rig"] [data-control-family="toolbar"][data-control="true"] {
    --cui-toolbar-item-radius: 0px;
    --cui-toolbar-item-shadow: none;
    font-weight: 600;
  }

  [data-skin="rig"] [data-control-family="code-diff"][data-slot="expand-button"][data-control="true"] {
    --cui-code-diff-expand-button-radius: 0px;
    --cui-code-diff-expand-button-shadow: none;
    font-weight: 600;
  }

  [data-skin="rig"] [data-control-family][data-control="true"]:hover {
    transform: translate(-1px, -1px);
  }

  [data-skin="rig"] [data-control-family][data-control="true"]:active {
    transform: translate(1px, 1px);
    filter: brightness(0.94);
  }

  [data-skin="rig"] [data-control-family="button"][data-control="true"][data-variant="solid"]:not(:disabled):not([data-disabled]):hover {
    filter: drop-shadow(3px 4px 0 oklch(from var(--foreground) l c h / 0.32));
  }

  [data-skin="rig"] [data-control-family="button"][data-control="true"][data-variant="solid"]:not(:disabled):not([data-disabled]):active {
    filter: drop-shadow(1px 1px 0 oklch(from var(--foreground) l c h / 0.4)) brightness(0.94);
  }

  [data-skin="rig"] [data-control-family][data-control="true"]:disabled,
  [data-skin="rig"] [data-control-family][data-control="true"][data-disabled] {
    transform: none;
    filter: none;
  }

  [data-skin="rig"] [data-control-family="button"][data-control="true"][data-variant="solid"] {
    --cui-button-bg: var(--primary);
    --cui-button-bg-image: linear-gradient(180deg, oklch(1 0 0 / 0.08), transparent 46%);
    --cui-button-foreground: var(--primary-foreground);
  }

  [data-skin="rig"] [data-control-family="button"][data-control="true"][data-variant="solid"]:hover {
    --cui-button-bg-image: linear-gradient(180deg, oklch(1 0 0 / 0.1), transparent 52%);
  }
  [data-skin="rig"]
    [data-control-family="button"][data-control="true"]:is([data-variant="surface"], [data-variant="ghost"], [data-variant="quiet"]) {
    --cui-button-bg: oklch(from var(--foreground) l c h / 0.04);
    --cui-button-bg-image: none;
    --cui-button-shadow: inset 0 0 0 1.5px oklch(from var(--foreground) l c h / 0.5);
  }

  [data-skin="rig"]
    [data-control-family="button"][data-control="true"]:is([data-variant="surface"], [data-variant="ghost"], [data-variant="quiet"]):hover {
    --cui-button-hover-bg: oklch(from var(--foreground) l c h / 0.09);
    --cui-button-hover-shadow: inset 0 0 0 1.5px var(--primary), inset 0 0 0 5px oklch(from var(--primary) l c h / 0.12);
  }

  /* User bubble = bg-primary coral both modes. Dark uses a deeper coral so the shared cream ink
   * keeps AA contrast against the bubble. */
  :is(.dark[data-skin="rig"], :where(.dark) [data-skin="rig"], [data-skin="rig"] :where(.dark))
  [data-slot="content"][data-role="user"][data-control-family="chat-message"] {
    --cui-chat-message-background: oklch(0.444 0.1277 32.246);
    --cui-chat-message-foreground: oklch(0.9313 0.0143 81.504);
  }

  /* --cui-tabs-trigger-radius is the one radius: list, tab and indicator all derive from it. */
  [data-skin="rig"] :where([data-slot="root"][data-control-family="tabs"]) {
    --cui-tabs-trigger-radius: 0px;
    --cui-tabs-active-foreground: var(--primary-foreground);
    --cui-tabs-indicator-background: var(--primary);
    --cui-tabs-indicator-shadow: 0 0 0 1px oklch(from var(--primary) l c h / 0.35);
  }

  /* Crosshair L-ticks in 4 corners: ::before=TL+BR, ::after=TR+BL, each a horiz+vert hairline; inset so they read despite overflow clipping. */
  [data-skin="rig"] [data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"],
  [data-skin="rig"] [data-slot="root"][data-control-family="code-block-editor"],
  [data-skin="rig"] [data-control-ui="dialog"][data-slot="content"][data-control-family="popup"],
  [data-skin="rig"] [data-control-ui="chat-composer"][data-slot="shell"][data-control-family="chat-composer"] {
    position: relative;
    --rig-tick: 11px;
    --rig-tick-w: 1.5px;
    --rig-tick-inset: 7px;
    --rig-tick-c: oklch(from var(--primary) l c h / 0.6);
  }

  [data-skin="rig"] [data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"]::before,
  [data-skin="rig"] [data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"]::after,
  [data-skin="rig"] [data-slot="root"][data-control-family="code-block-editor"]::before,
  [data-skin="rig"] [data-slot="root"][data-control-family="code-block-editor"]::after,
  [data-skin="rig"] [data-control-ui="dialog"][data-slot="content"][data-control-family="popup"]::before,
  [data-skin="rig"] [data-control-ui="dialog"][data-slot="content"][data-control-family="popup"]::after,
  [data-skin="rig"] [data-control-ui="chat-composer"][data-slot="shell"][data-control-family="chat-composer"]::before,
  [data-skin="rig"] [data-control-ui="chat-composer"][data-slot="shell"][data-control-family="chat-composer"]::after {
    content: "";
    position: absolute;
    inset: var(--rig-tick-inset);
    pointer-events: none;
    z-index: 2;
  }

  [data-skin="rig"] [data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"]::before,
  [data-skin="rig"] [data-slot="root"][data-control-family="code-block-editor"]::before,
  [data-skin="rig"] [data-control-ui="dialog"][data-slot="content"][data-control-family="popup"]::before,
  [data-skin="rig"] [data-control-ui="chat-composer"][data-slot="shell"][data-control-family="chat-composer"]::before {
    background:
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 0 0 / var(--rig-tick) var(--rig-tick-w) no-repeat,
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 0 0 / var(--rig-tick-w) var(--rig-tick) no-repeat,
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 100% 100% / var(--rig-tick) var(--rig-tick-w) no-repeat,
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 100% 100% / var(--rig-tick-w) var(--rig-tick) no-repeat;
  }

  [data-skin="rig"] [data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"]::after,
  [data-skin="rig"] [data-slot="root"][data-control-family="code-block-editor"]::after,
  [data-skin="rig"] [data-control-ui="dialog"][data-slot="content"][data-control-family="popup"]::after,
  [data-skin="rig"] [data-control-ui="chat-composer"][data-slot="shell"][data-control-family="chat-composer"]::after {
    background:
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 100% 0 / var(--rig-tick) var(--rig-tick-w) no-repeat,
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 100% 0 / var(--rig-tick-w) var(--rig-tick) no-repeat,
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 0 100% / var(--rig-tick) var(--rig-tick-w) no-repeat,
      linear-gradient(var(--rig-tick-c), var(--rig-tick-c)) 0 100% / var(--rig-tick-w) var(--rig-tick) no-repeat;
  }

  /* Composer ticks light coral + frame on focus: "armed" state. */
  [data-skin="rig"] [data-control-ui="chat-composer"][data-slot="shell"][data-control-family="chat-composer"]:focus-within {
    --rig-tick-c: var(--primary);
    --cui-chat-composer-shell-shadow: inset 0 0 0 1.5px oklch(from var(--primary) l c h / 0.55);
  }

  [data-skin="rig"] [data-control-ui="dropdown-menu"][data-popup-part="list-surface"][data-control-family="popup"],
  [data-skin="rig"] [data-control-ui="select"][data-popup-part="list-surface"][data-control-family="popup"] {
    --cui-popup-radius: 0px;
    --cui-popup-item-radius: 0px;
    --cui-popup-border-width: 1.5px;
    --cui-popup-border-color: oklch(from var(--foreground) l c h / 0.55);
    --cui-popup-shadow: inset 0 2px 0 var(--primary);
  }

  [data-skin="rig"] [data-control-ui="dropdown-menu"][data-slot="item"][data-control-family="popup"],
  [data-skin="rig"] [data-control-ui="select"][data-slot="item"][data-control-family="popup"] {
    transition:
      background-color var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard),
      transform var(--duration-fast) var(--ease-standard);
  }

  [data-skin="rig"] [data-control-ui="dropdown-menu"][data-slot="item"][data-control-family="popup"]:hover,
  [data-skin="rig"] [data-control-ui="dropdown-menu"][data-slot="item"][data-highlighted][data-control-family="popup"],
  [data-skin="rig"] [data-control-ui="select"][data-slot="item"][data-control-family="popup"]:hover,
  [data-skin="rig"] [data-control-ui="select"][data-slot="item"][data-highlighted][data-control-family="popup"] {
    box-shadow: inset 2px 0 0 var(--primary);
    transform: translateX(2px);
  }

  [data-skin="rig"] :where([data-slot="root"][data-control-family="sidebar"]) {
    --cui-sidebar-menu-button-radius: 0px;
    --cui-sidebar-menu-button-hover-shadow: inset 2px 0 0 var(--primary);
    --cui-sidebar-menu-button-active-shadow: inset 2px 0 0 var(--primary);
  }

  [data-skin="rig"] [data-slot="menu-button"][data-control-family="sidebar"] {
    transition:
      background-color var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard),
      transform var(--duration-fast) var(--ease-standard);
  }

  [data-skin="rig"] [data-slot="menu-button"][data-control-family="sidebar"]:hover,
  [data-skin="rig"] [data-slot="menu-button"][data-active="true"][data-control-family="sidebar"] {
    transform: translateX(2px);
  }

  /* Group labels = mono uppercase eyebrows (matches reference's "DATA EXTRACTION"/"001" style). */
  [data-skin="rig"] [data-slot="group-label"][data-control-family="sidebar"],
  [data-skin="rig"] [data-control-ui="dropdown-menu"][data-slot="label"][data-control-family="popup"] {
    font-family: var(--font-mono);
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 600;
    font-size: 0.68rem;
  }

  [data-skin="rig"] [data-control-ui="tooltip"][data-popup-part="surface"][data-control-family="popup"] {
    --cui-popup-radius: 0px;
    --cui-popup-border-width: 1.5px;
    --cui-popup-border-color: oklch(from var(--primary) l c h / 0.5);
    font-family: var(--font-mono);
    letter-spacing: 0.04em;
  }
}

/* Brutalist coral, squared corners, dense type. */

[data-skin="rig"] {
  --font-sans: "Helvetica Neue", "Arial Nova", Arial, "Segoe UI", ui-sans-serif, sans-serif;
  --font-mono: "JetBrains Mono", "IBM Plex Mono", ui-monospace, monospace;

  /* THE one radius knob: 0 squares every control + surface (the chamfer is added in skin.css). */
  --radius: 0px;

  --padding-x: 18px;
  --padding-y: 11px;
  --control-h: 40px;

  /* Flat + matte: brutalist controls carry their weight with fill + chamfer, not elevation. */
  --shadow-size: 0;

  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;
  --overlay-opacity: 0.6;
  --backdrop-blur-overlay: 0px;

  --duration-base: 130ms;
  --duration-fast: 85ms;
  --duration-slow: 210ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);

  --muted: oklch(0.9425 0.0104 79);
  --muted-foreground: oklch(0.52 0.0224 72);
  --secondary: oklch(0.9425 0.0104 79);
  --accent: oklch(0.9295 0.0118 77);
  --destructive: oklch(0.568 0.1961 32);
  --destructive-foreground: oklch(0.9852 0.0058 85);
  --border: oklch(0.8851 0.0135 76 / var(--ring-opacity));
  --input: oklch(0.8851 0.0135 76);
  --ring: oklch(0.6903 0.0198 74);
  --focus-ring: var(--foreground);
  /* every control is chamfered by clip-path, which eats an outward ring; the indicator draws inside it */
  --focus-ring-offset: -3px;
  --text-label: 0.75rem;
  --radius-control: calc(var(--radius) * 2);
  --radius-field: calc(var(--radius) * 2.2);
  --radius-panel: calc(var(--radius) * 2.6);
  --radius-scene: calc(var(--radius) * 2.8);
  --radius-popup-item: calc(var(--radius-control) * 0.6);
  --shadow-color: oklch(0.2986 0.0421 63);
  --shadow-opacity: 1;
  --ease-emphasized: cubic-bezier(0.16, 1, 0.3, 1);
  --scroll-fade-size: 2rem;
  --popover-padding: 0.25rem;
}

:root:not(.dark)[data-skin="rig"],
:where(:not(.dark)) [data-skin="rig"] {
  /* Coral = ACCENT not page bg; surfaces warm off-white (inverse of dark band's near-black stack).
   * canvas = paper; card/background/popover = near-white surfaces above it.
   * The filled primary is dark enough for white ink to clear WCAG AA. */
  --primary: oklch(0.54 0.1892 32.312);
  --primary-foreground: oklch(0.9852 0.0058 85);
  --foreground: oklch(0.2168 0.0113 55.716);
  --secondary-foreground: oklch(0.2168 0.0113 55.716);
  --accent-foreground: oklch(0.2168 0.0113 55.716);
  /* Clear of --muted (0.9425) — matching lightness makes muted surfaces vanish into the page. */
  --canvas: oklch(0.96 0.0084 63.977);
  --background: oklch(0.9789 0.0041 74.929);
  --card: oklch(0.9933 0.0016 81.514);
  --card-foreground: oklch(0.2168 0.0113 55.716);
  --popover: oklch(0.9933 0.0016 81.514);
  --popover-foreground: oklch(0.2168 0.0113 55.716);
}

.dark[data-skin="rig"],
:where(.dark) [data-skin="rig"] {
  --primary: oklch(0.54 0.1833 32.21);
  --primary-foreground: oklch(0.9852 0.0058 85);
  --foreground: oklch(0.9313 0.0143 81.504);
  --secondary-foreground: oklch(0.9313 0.0143 81.504);
  --accent-foreground: oklch(0.9313 0.0143 81.504);
  --canvas: oklch(0.1576 0.0041 48.447);
  --background: oklch(0.1812 0.0051 48.425);
  --card: oklch(0.204 0.0058 48.423);
  --card-foreground: oklch(0.9313 0.0143 81.504);
  --popover: oklch(0.204 0.0058 48.423);
  --popover-foreground: oklch(0.9313 0.0143 81.504);

  --muted: oklch(0.2668 0.0132 66);
  --muted-foreground: oklch(0.7405 0.0175 76);
  --secondary: oklch(0.2668 0.0132 66);
  --accent: oklch(0.2864 0.0141 67);
  --destructive: oklch(0.551 0.1799 32);
  --destructive-foreground: oklch(0.9645 0.008 84);
  --border: oklch(0.3082 0.0147 67 / var(--ring-opacity));
  --input: oklch(0.3082 0.0147 67);
  --ring: oklch(0.5521 0.0181 70);
  --focus-ring: var(--foreground);
  --shadow-color: oklch(0 0 0);
}
